'use client';

import { useEffect, useId, useRef, useState } from 'react';
import type { KeyboardEvent, MouseEvent } from 'react';
import './product-quick-view.css';

export interface ProductQuickViewImage {
  id: string;
  src: string;
  alt: string;
}

export interface ProductQuickViewVariant {
  id: string;
  label: string;
  color?: string;
  images: ProductQuickViewImage[];
  price?: string;
}

export interface ProductQuickViewSpecification {
  label: string;
  value: string;
}

export interface ProductQuickViewSelection {
  variant?: ProductQuickViewVariant;
  image?: ProductQuickViewImage;
}

export interface ProductQuickViewProps {
  title: string;
  description: string;
  price: string;
  images: ProductQuickViewImage[];
  eyebrow?: string;
  subtitle?: string;
  variants?: ProductQuickViewVariant[];
  specifications?: ProductQuickViewSpecification[];
  defaultVariant?: string;
  defaultImage?: string;
  action?: { label: string; href: string };
  onSelectionChange?: (selection: ProductQuickViewSelection) => void;
  onOpenChange?: (open: boolean) => void;
  className?: string;
}

/** A product card with an intentionally opened native product-detail dialog. */
export function ProductQuickView({
  title,
  description,
  price,
  images,
  eyebrow,
  subtitle,
  variants = [],
  specifications = [],
  defaultVariant,
  defaultImage,
  action,
  onSelectionChange,
  onOpenChange,
  className = '',
}: ProductQuickViewProps) {
  const [variantId, setVariantId] = useState(defaultVariant ?? variants[0]?.id ?? '');
  const [imageId, setImageId] = useState(defaultImage ?? '');
  const [expanded, setExpanded] = useState(false);
  const isOpen = useRef(false);
  const modal = useRef<HTMLDialogElement>(null);
  const opener = useRef<HTMLButtonElement>(null);
  const imageButtons = useRef(new Map<string, HTMLButtonElement>());
  const backdropStarted = useRef(false);
  const instance = useId();
  const titleId = `ac-quick-view-title-${instance}`;
  const dialogId = `ac-quick-view-dialog-${instance}`;
  const dialogTitleId = `${dialogId}-title`;
  const descriptionId = `${dialogId}-description`;
  const variant = variants.find(item => item.id === variantId) ?? variants[0];
  const currentImages = variant?.images.length ? variant.images : images;
  const foundImage = currentImages.findIndex(item => item.id === imageId);
  const imageIndex = foundImage < 0 ? 0 : foundImage;
  const image = currentImages[imageIndex];
  const currentPrice = variant?.price ?? price;

  useEffect(() => {
    if (!expanded) return;
    const previousOverflow = document.body.style.overflow;
    document.body.style.overflow = 'hidden';
    return () => { document.body.style.overflow = previousOverflow; };
  }, [expanded]);

  useEffect(() => {
    const dialog = modal.current;
    return () => { if (dialog?.open) dialog.close(); };
  }, []);

  function publishOpen(next: boolean) {
    if (isOpen.current === next) return;
    isOpen.current = next;
    setExpanded(next);
    onOpenChange?.(next);
  }

  function open() {
    if (!modal.current || modal.current.open) return;
    modal.current.showModal();
    publishOpen(true);
  }

  function close() {
    if (modal.current?.open) modal.current.close();
    publishOpen(false);
    opener.current?.focus({ preventScroll: true });
  }

  function chooseImage(index: number) {
    const next = currentImages[index];
    if (!next || next.id === image?.id) return;
    setImageId(next.id);
    onSelectionChange?.({ variant, image: next });
  }

  function chooseVariant(next: ProductQuickViewVariant) {
    if (next.id === variant?.id) return;
    const nextImage = (next.images.length ? next.images : images)[0];
    setVariantId(next.id);
    setImageId(nextImage?.id ?? '');
    onSelectionChange?.({ variant: next, image: nextImage });
  }

  function onImageKey(event: KeyboardEvent<HTMLButtonElement>, index: number) {
    let next: number;
    if (event.key === 'ArrowRight') next = (index + 1) % currentImages.length;
    else if (event.key === 'ArrowLeft') next = (index - 1 + currentImages.length) % currentImages.length;
    else if (event.key === 'Home') next = 0;
    else if (event.key === 'End') next = currentImages.length - 1;
    else return;
    event.preventDefault();
    chooseImage(next);
    imageButtons.current.get(currentImages[next].id)?.focus({ preventScroll: true });
    imageButtons.current.get(currentImages[next].id)?.scrollIntoView({ block: 'nearest', inline: 'nearest' });
  }

  function isBackdrop(event: MouseEvent<HTMLDialogElement>) {
    if (event.target !== event.currentTarget) return false;
    const bounds = event.currentTarget.getBoundingClientRect();
    return event.clientX < bounds.left || event.clientX > bounds.right || event.clientY < bounds.top || event.clientY > bounds.bottom;
  }

  return <article className={`ac-product-quick-view ${className}`.trim()} aria-labelledby={titleId}>
    <div className="ac-quick-view-card-stage">
      {eyebrow && <span className="ac-quick-view-eyebrow">{eyebrow}</span>}
      {image ? <img className="ac-quick-view-card-image" src={image.src} alt={image.alt} loading="lazy" /> : <span className="ac-quick-view-empty">Image coming soon</span>}
      <button ref={opener} type="button" className="ac-quick-view-trigger" aria-haspopup="dialog" aria-expanded={expanded} aria-controls={dialogId} aria-label={`Quick view ${title}`} onClick={open}>
        <span>Quick view</span><span aria-hidden="true">↗</span>
      </button>
    </div>
    <div className="ac-quick-view-card-info">
      <div><h3 id={titleId}>{title}</h3>{subtitle && <p>{subtitle}</p>}</div>
      <span className="ac-quick-view-card-price">{currentPrice}</span>
    </div>
    <dialog
      ref={modal}
      id={dialogId}
      className="ac-quick-view-dialog"
      aria-labelledby={dialogTitleId}
      aria-describedby={descriptionId}
      onCancel={event => { event.preventDefault(); close(); }}
      onClose={() => { if (!modal.current?.open && isOpen.current) close(); }}
      onPointerDown={event => { backdropStarted.current = isBackdrop(event); }}
      onPointerCancel={() => { backdropStarted.current = false; }}
      onClick={event => { if (backdropStarted.current && isBackdrop(event)) close(); backdropStarted.current = false; }}
    >
      <div className="ac-quick-view-dialog-shell">
        <header className="ac-quick-view-dialog-top"><span>{eyebrow ?? 'A CLOSER LOOK'}</span><button type="button" className="ac-quick-view-close" autoFocus aria-label={`Close ${title} quick view`} onClick={close}><span>Close</span><span aria-hidden="true">×</span></button></header>
        <div className="ac-quick-view-dialog-layout">
          <div className="ac-quick-view-gallery">
            <div className="ac-quick-view-image-stage">{image ? <img key={`${variant?.id ?? ''}-${image.id}`} src={image.src} alt={image.alt} className="ac-quick-view-large-image" /> : <span className="ac-quick-view-empty">Image coming soon</span>}</div>
            {currentImages.length > 1 && <div className="ac-quick-view-gallery-bottom"><div className="ac-quick-view-thumbnails" role="group" aria-label={`Images of ${title}`}>
              {currentImages.map((item, index) => <button key={item.id} ref={element => { if (element) imageButtons.current.set(item.id, element); else imageButtons.current.delete(item.id); }} type="button" aria-label={`Show image ${index + 1}: ${item.alt}`} aria-pressed={item.id === image?.id} onClick={() => chooseImage(index)} onKeyDown={event => onImageKey(event, index)}><img src={item.src} alt="" loading="lazy" /></button>)}
            </div><span className="ac-quick-view-image-count" aria-live="polite" aria-atomic="true">{imageIndex + 1} / {currentImages.length}</span></div>}
          </div>
          <div className="ac-quick-view-details">
            <div className="ac-quick-view-dialog-heading"><p className="ac-quick-view-overline">CONSIDERED IN EVERY DETAIL</p><h2 id={dialogTitleId}>{title}</h2>{subtitle && <p className="ac-quick-view-subtitle">{subtitle}</p>}</div>
            <p className="ac-quick-view-price" aria-live="polite" aria-atomic="true">{currentPrice}</p>
            <p id={descriptionId} className="ac-quick-view-description">{description}</p>
            {variants.length > 0 && <fieldset className="ac-quick-view-finishes"><legend>Finish <span aria-live="polite">/ {variant?.label}</span></legend><div>{variants.map(item => <button type="button" key={item.id} aria-label={`Finish: ${item.label}`} aria-pressed={item.id === variant?.id} onClick={() => chooseVariant(item)}><span className="ac-quick-view-swatch" style={{ background: item.color ?? 'currentColor' }} aria-hidden="true" /><span>{item.label}</span><span className="ac-quick-view-finish-indicator" aria-hidden="true">{item.id === variant?.id ? '●' : '○'}</span></button>)}</div></fieldset>}
            {specifications.length > 0 && <dl className="ac-quick-view-specifications">{specifications.map((item, index) => <div key={`${item.label}-${index}`}><dt>{item.label}</dt><dd>{item.value}</dd></div>)}</dl>}
            {action && <a className="ac-quick-view-action" href={action.href} onClick={close}><span>{action.label}</span><span aria-hidden="true">↗</span></a>}
          </div>
        </div>
      </div>
    </dialog>
  </article>;
}

.ac-product-quick-view {
  --ac-quick-view-surface: #eeeee9;
  --ac-quick-view-stage: #e1e2dc;
  --ac-quick-view-ink: #242824;
  --ac-quick-view-muted: #646961;
  --ac-quick-view-line: #cdd0c7;
  --ac-quick-view-accent: #354e3a;
  color: var(--ac-quick-view-ink);
  container-type: inline-size;
  font-family: Arial, Helvetica, sans-serif;
  min-width: 0;
}
.ac-product-quick-view *, .ac-product-quick-view *::before, .ac-product-quick-view *::after { box-sizing: border-box; }
.ac-product-quick-view button, .ac-product-quick-view a { -webkit-tap-highlight-color: transparent; }
.ac-product-quick-view button { font: inherit; color: inherit; cursor: pointer; }
.ac-product-quick-view :focus-visible { outline: 2px solid var(--ac-quick-view-accent); outline-offset: 4px; }
.ac-quick-view-card-stage { position: relative; display: grid; place-items: center; aspect-ratio: var(--ac-quick-view-card-ratio, 1.16); min-height: 240px; background: var(--ac-quick-view-stage); padding: 40px 22px 58px; }
.ac-quick-view-eyebrow { position: absolute; top: 21px; left: 22px; color: var(--ac-quick-view-muted); font-size: 10px; line-height: 1.5; letter-spacing: .08em; }
.ac-quick-view-card-image { position: absolute; inset: 40px 22px 58px; display: block; width: calc(100% - 44px); height: calc(100% - 98px); object-fit: contain; transition: transform 650ms cubic-bezier(.2,.8,.2,1); }
.ac-quick-view-trigger { position: absolute; bottom: 18px; right: 18px; display: flex; align-items: center; justify-content: space-between; gap: 28px; min-height: 44px; padding: 0 14px; border: 1px solid var(--ac-quick-view-ink); border-radius: 0; background: var(--ac-quick-view-surface); font-size: 12px !important; transition: background 180ms, color 180ms; }
.ac-quick-view-trigger > span:last-child { font-size: 21px; }
.ac-quick-view-trigger:hover { background: var(--ac-quick-view-ink); color: var(--ac-quick-view-surface); }
.ac-quick-view-card-info { display: flex; align-items: start; justify-content: space-between; gap: 16px; padding: 19px 1px 20px; }
.ac-quick-view-card-info > div { min-width: 0; }
.ac-quick-view-card-info h3 { margin: 0; font-size: clamp(19px, 5cqi, 26px); font-weight: 500; line-height: 1.2; letter-spacing: -.04em; overflow-wrap: anywhere; }
.ac-quick-view-card-info p { margin: 7px 0 0; color: var(--ac-quick-view-muted); font-size: 11px; line-height: 1.5; }
.ac-quick-view-card-price { padding-top: 3px; font-size: 14px; white-space: nowrap; }
.ac-quick-view-empty { color: var(--ac-quick-view-muted); font-size: 13px; }
.ac-quick-view-dialog { width: min(1120px, calc(100vw - 40px)); max-width: none; max-height: calc(100dvh - 40px); margin: auto; padding: 0; border: 1px solid var(--ac-quick-view-line); border-radius: 0; color: var(--ac-quick-view-ink); background: var(--ac-quick-view-surface); overflow: auto; overscroll-behavior: contain; container: ac-quick-view-dialog / inline-size; }
.ac-quick-view-dialog::backdrop { background: #171b17aa; backdrop-filter: blur(8px); }
.ac-quick-view-dialog[open] { animation: ac-quick-view-open 350ms cubic-bezier(.18,.8,.2,1) both; }
.ac-quick-view-dialog-top { position: sticky; z-index: 2; top: 0; display: flex; justify-content: space-between; align-items: center; gap: 20px; min-height: 65px; padding: 8px 25px; background: var(--ac-quick-view-surface); border-bottom: 1px solid var(--ac-quick-view-line); }
.ac-quick-view-dialog-top > span { color: var(--ac-quick-view-muted); font-size: 10px; letter-spacing: .08em; }
.ac-quick-view-close { display: flex; align-items: center; gap: 20px; min-height: 44px; min-width: 44px; border: 0; border-radius: 0; padding: 0 0 0 10px; background: transparent; font-size: 11px !important; }
.ac-quick-view-close > span:last-child { font-size: 25px; font-weight: 400; }
.ac-quick-view-dialog-layout { display: grid; grid-template-columns: 1.08fr 1fr; min-width: 0; }
.ac-quick-view-gallery { display: flex; flex-direction: column; justify-content: center; min-width: 0; padding: 26px; background: var(--ac-quick-view-stage); }
.ac-quick-view-image-stage { position: relative; display: grid; place-items: center; width: 100%; aspect-ratio: 1.07; min-height: 220px; }
.ac-quick-view-large-image { position: absolute; inset: 0; display: block; width: 100%; height: 100%; object-fit: contain; animation: ac-quick-view-image 280ms ease-out both; }
.ac-quick-view-gallery-bottom { display: flex; justify-content: space-between; align-items: center; gap: 16px; margin-top: 20px; }
.ac-quick-view-thumbnails { display: flex; gap: 8px; padding: 5px; margin: -5px; overflow-x: auto; max-width: 100%; }
.ac-quick-view-thumbnails > button { flex: 0 0 55px; display: grid; place-items: center; height: 48px; padding: 3px; background: transparent; border: 1px solid transparent; border-radius: 0; }
.ac-quick-view-thumbnails > button[aria-pressed="true"] { border-color: var(--ac-quick-view-ink); background: #ffffff38; }
.ac-quick-view-thumbnails img { display: block; width: 100%; height: 100%; object-fit: contain; }
.ac-quick-view-image-count { flex: 0 0 auto; font-size: 10px; color: var(--ac-quick-view-muted); }
.ac-quick-view-details { min-width: 0; padding: clamp(26px, 3.7cqi, 46px); }
.ac-quick-view-overline { margin: 0 0 21px; color: var(--ac-quick-view-muted); font-size: 9px; line-height: 1.5; letter-spacing: .08em; }
.ac-quick-view-dialog-heading h2 { margin: 0; font-size: clamp(32px, 4.5cqi, 58px); font-weight: 400; line-height: 1.02; letter-spacing: -.065em; overflow-wrap: anywhere; }
.ac-quick-view-subtitle { margin: 12px 0 0; color: var(--ac-quick-view-muted); font-size: 11px; line-height: 1.5; }
.ac-quick-view-price { margin: 27px 0 20px; font-size: 23px; letter-spacing: -.04em; }
.ac-quick-view-description { margin: 0 0 26px; color: var(--ac-quick-view-muted); font-size: 12px; line-height: 1.8; white-space: pre-line; }
.ac-quick-view-finishes { margin: 0 0 23px; padding: 0; min-width: 0; border: 0; }
.ac-quick-view-finishes legend { margin-bottom: 12px; padding: 0; font-size: 11px; }
.ac-quick-view-finishes legend > span { color: var(--ac-quick-view-muted); }
.ac-quick-view-finishes > div { display: flex; flex-wrap: wrap; gap: 7px; }
.ac-quick-view-finishes button { display: flex; align-items: center; gap: 7px; min-height: 44px; max-width: 100%; padding: 8px 10px; background: transparent; border: 1px solid var(--ac-quick-view-line); border-radius: 0; font-size: 10px; }
.ac-quick-view-finishes button > span:nth-child(2) { min-width: 0; overflow-wrap: anywhere; }
.ac-quick-view-finishes button[aria-pressed="true"] { border-color: var(--ac-quick-view-ink); }
.ac-quick-view-swatch { width: 15px; height: 15px; flex: 0 0 auto; border-radius: 50%; border: 1px solid #24282429; }
.ac-quick-view-finish-indicator { font-size: 8px; }
.ac-quick-view-specifications { margin: 0 0 27px; border-top: 1px solid var(--ac-quick-view-line); }
.ac-quick-view-specifications > div { display: flex; justify-content: space-between; gap: 20px; padding: 11px 0; border-bottom: 1px solid var(--ac-quick-view-line); font-size: 10px; line-height: 1.6; }
.ac-quick-view-specifications dt { color: var(--ac-quick-view-muted); }
.ac-quick-view-specifications dd { margin: 0; text-align: right; overflow-wrap: anywhere; }
.ac-quick-view-action { display: flex; align-items: center; justify-content: space-between; gap: 20px; min-height: 52px; padding: 14px 18px; color: var(--ac-quick-view-surface); background: var(--ac-quick-view-accent); text-decoration: none; font-size: 12px; transition: filter 180ms; }
.ac-quick-view-action > span:last-child { font-size: 23px; line-height: 1; }
.ac-quick-view-action:hover { filter: brightness(1.15); }
@container ac-quick-view-dialog (width < 720px) {
  .ac-quick-view-dialog-layout { grid-template-columns: minmax(0, 1fr); }
  .ac-quick-view-gallery { padding: 18px 23px; }
  .ac-quick-view-image-stage { aspect-ratio: 1.7; min-height: 170px; }
  .ac-quick-view-gallery-bottom { margin-top: 10px; }
  .ac-quick-view-details { padding: 26px; }
  .ac-quick-view-overline { margin-bottom: 14px; }
  .ac-quick-view-dialog-heading h2 { font-size: 39px; }
  .ac-quick-view-price { margin-top: 22px; }
}
@media (max-width: 480px) {
  .ac-quick-view-dialog { width: calc(100vw - 20px); max-height: calc(100dvh - 20px); }
  .ac-quick-view-dialog-top { padding-inline: 20px; }
}
@media (hover: hover) and (pointer: fine) {
  .ac-product-quick-view:hover .ac-quick-view-card-image { transform: translateY(-4px) scale(1.025); }
}
@keyframes ac-quick-view-open { from { opacity: 0; transform: translateY(18px) scale(.985); } to { opacity: 1; transform: none; } }
@keyframes ac-quick-view-image { from { opacity: .3; transform: translateY(5px); } to { opacity: 1; transform: none; } }
@media (prefers-reduced-motion: reduce) {
  .ac-product-quick-view *, .ac-product-quick-view *::before, .ac-product-quick-view *::after { animation: none !important; transition: none !important; }
  .ac-product-quick-view:hover .ac-quick-view-card-image { transform: none; }
}
